81	  bnep_cb.reg_info.pL2CA_ConfigInd_Cb = nullptr;
82	  bnep_cb.reg_info.pL2CA_ConfigCfm_Cb = bnep_config_cfm;
83	  bnep_cb.reg_info.pL2CA_DisconnectInd_Cb = bnep_disconnect_ind;
84	  bnep_cb.reg_info.pL2CA_DataInd_Cb = bnep_data_ind;
85	  bnep_cb.reg_info.pL2CA_CongestionStatus_Cb = bnep_congestion_ind;
86	  bnep_cb.reg_info.pL2CA_Error_Cb = bnep_on_l2cap_error;
87	
88	  /* Now, register with L2CAP */
89	  if (!L2CA_Register2(BT_PSM_BNEP, bnep_cb.reg_info, false /* enable_snoop */,
90	                      nullptr, BNEP_MTU_SIZE, BNEP_MTU_SIZE,
91	                      BTA_SEC_AUTHENTICATE | BTA_SEC_ENCRYPT)) {
92	    BNEP_TRACE_ERROR("BNEP - Registration failed");
93	    return BNEP_SECURITY_FAIL;
94	  }
95	
96	  return BNEP_SUCCESS;
